// Generated by build_web.py. Every release URL is immutable and content-checked.
const RELEASE=__RELEASE__;
const ASSETS=__ASSETS__;
const SHELL_SHA=__SHELL_SHA__;
const ROOT=new URL('./',self.location.href),PREFIX='queen-street:'+ROOT.pathname+':',CACHE=PREFIX+RELEASE;
const SHELL=new URL('./?offline-shell='+RELEASE,ROOT).href;
const META=new URL('./?cache-metadata',ROOT).href;
const reports=new Map(),asked=new Set();
async function tellAll(message){const clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const client of clients)if(client.url.startsWith(ROOT.href))client.postMessage(message);}
async function digest(response){
 const bytes=await response.clone().arrayBuffer(),digest=await crypto.subtle.digest('SHA-256',bytes);
 return Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');
}
async function verified(url,sha){
 const response=await fetch(new URL(url,ROOT),{cache:url.startsWith('releases/')?'force-cache':'reload'});
 if(!response.ok||response.type==='opaque')throw Error('Incomplete release: '+url);
 if(await digest(response)!==sha)throw Error('Release hash mismatch: '+url);
 return response;
}
self.addEventListener('install',event=>event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 try{
   const shell=await fetch(new URL('index.html',ROOT),{cache:'no-store'});
   if(!shell.ok||!(await shell.clone().text()).includes('name="queen-street-release" content="'+RELEASE+'"')||await digest(shell)!==SHELL_SHA)throw Error('Release shell is not ready');
   await cache.put(SHELL,shell);
   let index=0;
   const results=await Promise.allSettled(Array.from({length:3},async()=>{while(index<ASSETS.length){const asset=ASSETS[index++];await cache.put(new URL(asset.url,ROOT),await verified(asset.url,asset.sha256));}}));
   for(const result of results)if(result.status==='rejected')throw result.reason;
   // A completion marker also supplies a monotonic generation. Cleanup must
   // never remove an installing cache or a newer waiting release.
   let generation=0;
   for(const key of await caches.keys())if(key.startsWith(PREFIX)){try{const metadata=await (await (await caches.open(key)).match(META))?.json();generation=Math.max(generation,metadata?.generation??0);}catch{}}
   await cache.put(META,new Response(JSON.stringify({release:RELEASE,generation:generation+1}),{headers:{'Content-Type':'application/json'}}));
 }catch(error){await caches.delete(CACHE);throw error;}
 // Updates wait for the game to reach a safe reload point. A failed install
 // never replaces the current working cache or worker.
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{await self.clients.claim();await tellAll({type:'REPORT_VERSION'});await tellAll({type:'OFFLINE_READY',release:RELEASE});})()));
async function prune(){
 const clients=(await self.clients.matchAll({type:'window',includeUncontrolled:true})).filter(c=>c.url.startsWith(ROOT.href));
 for(const client of clients)if(!reports.has(client.id)&&!asked.has(client.id)){asked.add(client.id);client.postMessage({type:'REPORT_VERSION'});}
 // An old, frozen or unresponsive tab retains its assets until it reports the
 // current release or closes. This also works after a worker process restart.
 if(!clients.length||clients.some(client=>reports.get(client.id)!==RELEASE))return;
 const current=await (await (await caches.open(CACHE)).match(META))?.json();if(!Number.isFinite(current?.generation))return;
 for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE){
   let metadata;try{metadata=await (await (await caches.open(key)).match(META))?.json();}catch{}
   if(Number.isFinite(metadata?.generation)&&metadata.generation<current.generation)await caches.delete(key);
 }
}
self.addEventListener('message',event=>{
 if(event.data?.type==='ACTIVATE')event.waitUntil(self.skipWaiting());
 if(event.data?.type==='CLIENT_VERSION'&&event.source?.id){reports.set(event.source.id,event.data.release);event.waitUntil(prune());}
});
async function cachedAsset(request){
 const current=await caches.open(CACHE);let response=await current.match(request.url,{ignoreSearch:true});
 if(!response)for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE){response=await (await caches.open(key)).match(request.url,{ignoreSearch:true});if(response)break;}
 if(!response)return fetch(request);
 const range=request.headers.get('range');if(!range)return response;
 const bytes=await response.arrayBuffer(),match=/^bytes=(\d*)-(\d*)$/.exec(range);
 let start=match?.[1]?Number(match[1]):NaN,end=match?.[2]?Number(match[2]):bytes.byteLength-1;
 if(match&&!match[1]&&match[2]){start=Math.max(0,bytes.byteLength-Number(match[2]));end=bytes.byteLength-1;}
 end=Math.min(end,bytes.byteLength-1);
 if(!match||!Number.isFinite(start)||start>end||start>=bytes.byteLength)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+bytes.byteLength}});
 const headers=new Headers(response.headers);headers.delete('Content-Encoding');headers.set('Accept-Ranges','bytes');headers.set('Content-Range',`bytes ${start}-${end}/${bytes.byteLength}`);headers.set('Content-Length',end-start+1);
 return new Response(bytes.slice(start,end+1),{status:206,headers});
}
self.addEventListener('fetch',event=>{
 const request=event.request,url=new URL(request.url);
 if(request.method!=='GET'||url.origin!==ROOT.origin||!url.href.startsWith(ROOT.href))return;
 if(request.mode==='navigate'){event.respondWith((async()=>{const cache=await caches.open(CACHE);return await cache.match(SHELL)||fetch(request);})());return;}
 if(url.pathname.includes('/releases/')||ASSETS.some(asset=>new URL(asset.url,ROOT).pathname===url.pathname))event.respondWith(cachedAsset(request));
});
